json AgentHost::usage_chat_titles() const
{
    json found = json::object();
    if (!m_account || m_chat_titles_file.empty())
        return found;
    const json titles = read_chat_titles(m_chat_titles_file);
    // A report's row names itself and has no chat; a request of no chat has
    // a null one.
    for (const json& row : m_account->at("usage_30d").at("activity")) {
        const auto chat = row.find("chat_id");
        if (chat == row.end() || !chat->is_string())
            continue;
        const auto title = titles.find(chat->get<std::string>());
        if (title != titles.end())
            found[chat->get<std::string>()] = *title;
    }
    return found;
}

bool AgentHost::use_chat_model(const std::string& conversation_id, const ConversationMessage& assistant, bool by_person)
{
    if (!m_model_source)
        return true;
    ProjectStateDocument& document = m_persistence.document();
    // A chat the person has talked in stays on its provider: when its key is
    // gone, or its account signed out of, the turn fails rather than carry on
    // with another. Before the person's first message the picker shows the
    // default, and the chat takes it.
    if (const std::optional<ChatModelChoice> kept = document.chat_model(conversation_id); kept) {
        const std::vector<std::string> configured = m_model_source->configured_providers();
        if (std::find(configured.begin(), configured.end(), kept->provider) == configured.end() &&
            person_talked_before(conversation_id, assistant.in_reply_to)) {
            const ProviderProfile* profile = profile_for(kept->provider);
            const std::string      name    = profile ? profile->display_name : kept->provider;
            fail_stream(AgentError{"chat_provider_removed",
                                   profile && profile->account_sign_in ?
                                       // TRN %1% is an AI provider's account, such as JusPrin.
                                       Slic3r::format(translated(L("This chat ran on your %1% account. Sign in again to continue it, or start a new chat.")), name) :
                                       // TRN %1% is an AI provider, such as OpenAI.
                                       Slic3r::format(translated(L("This chat ran on %1%, and no %1% API key is set up now. Add the key in the AI settings to continue it, or start a new chat.")), name),
                                   false});
            return false;
        }
    }
    ChatModelChoice choice = chat_model_choice(conversation_id);
    if (const ProviderProfile* profile = profile_for(choice.provider); profile != nullptr && profile->account_sign_in) {
        if (!by_person)
            choice = app_turn_model(choice);
        if (choice.format.empty()) {
            // The account's model list has not named this model; it is asked
            // for again, and the person can send once it has.
            request_model_lists();
            fail_stream(AgentError{"account_models_unknown",
                                   translated(L("JusPrin hasn't loaded the AI models for your account yet. Try again in a moment.")), true});
            return false;

